'use strict';
const ICON_PATHS21={next:'M4 4h13l5 5v11H4z M9 12h8m-3-3 3 3-3 3',team:'M8 8a3 3 0 1 0 0-6 3 3 0 0 0 0 6 M17 10a3 3 0 1 0 0-6 3 3 0 0 0 0 6 M2 21v-5a6 6 0 0 1 12 0v5z M15 14h5l2 7h-6',info:'M4 3h16v14l-8 5-8-5z M12 7v6 M12 16v1',base:'M3 22V10L12 3l9 7v12z M8 22v-8h8v8 M7 10h10',database:'M3 3h18v5H3z M3 11h18v5H3z M3 19h18v4H3z M6 5h1m-1 8h1m-1 8h1',settings:'M2 5h20 M2 12h20 M2 19h20 M7 2v6 M16 9v6 M9 16v6',menu:'M3 5h18 M3 12h18 M3 19h18',match:'M3 3l8 8 M21 3l-8 8 M3 21l8-8 M21 21l-8-8',exit:'M3 2h10v20H3z M10 12h12m-5-5 5 5-5 5'};
function icon21(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ICON_PATHS21[name]||ICON_PATHS21.menu}"/></svg>`;}
if(!PAGES.some(p=>p[0]==='development'))PAGES.splice(PAGES.findIndex(p=>p[0]==='tactics'),0,['development','↗','Развитие']);
PAGES.push(['menu21','☰','Все разделы']);
let dashboardEvent21=null,newsIndex21=0;
function dashboardEventObject21(){return S.events.find(e=>e.id===dashboardEvent21)||nextEvent();}
function cycleDashboard21(step){let events=S.events.filter(e=>!e.done),index=events.findIndex(e=>e.id===(dashboardEvent21??nextEvent()?.id));if(!events.length)return;dashboardEvent21=events[(index+step+events.length)%events.length].id;go('home');}
function menuView21(){return head('ANCIENT MANAGER / 2.1','Все разделы','Управление клубом и соревнованиями.')+`<div class="all-sections21">${PAGES.filter(p=>p[0]!=='menu21').map(p=>`<button onclick="go('${p[0]}')"><span>${p[1]}</span><b>${p[2]}</b><small>Открыть →</small></button>`).join('')}</div>`;}
function miniClub21(id){let t=S.teams[id];return t?`<span class="mini-club21">${clubAvatar12(t,true)}<span>${esc(t.name)}</span></span>`:'<span class="mini-club21">Участник не определён</span>';}
function tableRows21(a,ids){let rows=ids.map(id=>({id,m:0,w:0,d:0,l:0,s:0}));if(a)for(let n of a.schedule||[]){if(!n.score||a.groupIds&&!n.groupMatch||a.stage6==='playoffs'&&isPlayoffV1(n))continue;let pair=n.pair.map(v=>resolve6(a,v));if(!pair.some(id=>ids.includes(id)))continue;let scores=n.score.split(':').map(Number);for(let side of [0,1]){let r=rows.find(r=>r.id===pair[side]);if(!r)continue;r.m++;if(scores[side]>scores[1-side]){r.w++;r.s+=3;}else if(scores[side]===scores[1-side]){r.d++;r.s++;}else r.l++;}}
 return rows.sort((a,b)=>b.s-a.s||b.w-a.w||a.id-b.id);}
function overviewGroups21(e){let live=S.active?.event===e?.id?S.active:null,a=live||e?.done&&e.schedule6?live||{schedule:e.schedule6,groupIds:e.groupIds6,gsl:e.gsl6,entrants:e.entrants,stage6:'groups'}:null,actual=a?.groupIds||a?.gsl?.map(g=>g.ids),ids=a?.entrants||e?.qualified13||S.teams.filter(t=>!t.fiction).slice(0,16).map(t=>t.id),groups=actual||Array.from({length:Math.ceil(ids.length/4)},(_,i)=>ids.slice(i*4,i*4+4));
 let isSwiss=!!a&&!actual;return `<section class="tournament-board21"><div class="white-heading21"><h1>${esc(e?.name||'Турниры сезона')}</h1><p>${live?esc(live.stage||'Групповой этап'):e?.done?'Итог турнира':'Подготовка к турниру'}</p></div><div class="group-panels21">${groups.map((group,i)=>`<section class="group-card21"><div class="group-header21"><b>${actual?'Группа '+String.fromCharCode(65+i):isSwiss?'Swiss · места '+(i*4+1)+'–'+(i*4+group.length):'Посев '+(i+1)}</b><span>М</span><span>В</span><span>Н</span><span>П</span><span>О</span></div><div class="group-table21">${tableRows21(a,group).map(r=>`<div class="group-row21 ${r.id===S.club?'own-club21':''}">${miniClub21(r.id)}<span>${r.m}</span><span>${r.w}</span><span>${r.d}</span><span>${r.l}</span><b>${r.s}</b></div>`).join('')}</div></section>`).join('')}</div><div class="board-foot21"><small>${actual?'Таблицы групп текущего турнира':isSwiss?'Swiss: таблица разбита на блоки для просмотра. Это не отдельные группы.':'Предварительный посев. Жеребьёвка участников ещё не проведена.'}</small>${live||e?.done?btn('Полная сетка →',`showBracket(${e.id})`):btn('Календарь →',"go('calendar')")}</div></section>`;}
function fixtureCard21(pair,day,title,stage,action,first=false){return `<button class="fixture-card21 ${first?'first-fixture21':''}" onclick="${action}"><div class="fixture-date21">${date(day)}</div><div class="fixture-logos21">${pair[0]!=null?clubAvatar12(S.teams[pair[0]]):'<span class="unknown-fixture21">?</span>'}<b>VS</b>${pair[1]!=null?clubAvatar12(S.teams[pair[1]]):'<span class="unknown-fixture21">?</span>'}</div><strong>${esc(title)}</strong><small>${esc(stage)}</small></button>`;}
function scheduleRail21(e){let a=S.active?.event===e?.id?S.active:null,fixtures=[];
 if(a){let known=a.schedule.filter((n,i)=>i>=a.cursor&&!n.score).map(n=>({n,pair:n.pair.map(v=>resolve6(a,v))})).filter(v=>v.pair.includes(S.club)&&v.pair.every(Number.isInteger)).slice(0,4);fixtures=known.map(({n,pair},i)=>fixtureCard21(pair,n.day13??S.day,e.name,n.label+' · BO'+n.bo,"go('match')",i===0));}
 if(!fixtures.length){let events=S.events.filter(v=>!v.done&&v.day>=(e?.day??S.day)).slice(0,4);fixtures=events.map((v,i)=>fixtureCard21([S.club,null],v.day,v.name,'Соперник после жеребьёвки',"go('calendar')",i===0));}
 return `<div class="schedule-rail21">${fixtures.join('')}${btn('Матч-центр →',"go('match')",true)}</div>`;}
home=function(){let e=dashboardEventObject21(),news=S.news.slice(0,5),index=news.length?newsIndex21%news.length:0;return `<div class="reference-dashboard21"><div class="reference-center21"><section class="news-board21"><div class="white-heading21"><h2>Новости</h2></div><div class="news-content21"><p>${esc(news[index]?.text||'Новый сезон. Новая история твоего клуба.')}</p><div class="news-dots21">${news.map((_,i)=>`<button class="${i===index?'selected':''}" aria-label="Новость ${i+1}" onclick="newsIndex21=${i};render()"></button>`).join('')}</div></div></section>${overviewGroups21(e)}</div>${scheduleRail21(e)}</div><div class="home-tools21"><span>Бюджет <b>${cash(S.budget)}</b></span><span>Подготовка <b>${Math.round(development21().preparation)}%</b></span><span>База ${development21().base}/5 · штаб ${development21().staff}/5</span>${btn('Зал наград',"go('trophies')")}${btn('Тактика',"go('tactics')")}</div>${typeof tiBanner==='function'?tiBanner():''}`;};
const renderBeforeLayout21=render;render=function(){renderBeforeLayout21();if(!S)return;let t=my();$('club').innerHTML=`${clubAvatar12(t,true)}<b>${esc(t.name).toUpperCase()}</b>`;
 let primary=[['home','info','Главная'],['squad','team','Управление командой'],['development','base','Развитие клуба'],['players','database','База игроков'],['menu21','settings','Все разделы']];
 $('nav').innerHTML=primary.map(([id,icon,label])=>`<button class="${page===id||id==='players'&&page==='player'?'active':''}" onclick="go('${id}')">${icon21(icon)}<span>${label}</span></button>`).join('');
 let label=S.active?'В матч-центр':nextEvent()?.day<=S.day?'Начать турнир':'Следующий день';$('advance').innerHTML=icon21('next')+`<span>${label}</span>`;
 if(document.body?.classList?.toggle)document.body.classList.toggle('reference-home21',page==='home');
 $('crumb').textContent=page==='player'?'Информация об игроке':PAGES.find(p=>p[0]===page)?.[2]||'Главная';
};
